import {setupPasswordRecovery} from './password-recovery.mjs';
import {appendRhythm,readRhythms,formatPace} from './rhythm.mjs';
import {analyze,SOURCES} from './physiology.mjs';
import {payloadOf,sessionForEdit,editFingerprint} from './sync-model.mjs';
const $=id=>document.getElementById(id);
const add=(tag,text,parent,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;parent.append(e);return e;};
const n=v=>v===null||v===undefined?'—':Number(v).toLocaleString('pt-BR',{maximumFractionDigits:2});
export function setupFeatures(api){setupPasswordRecovery(async()=>{const {getClient}=await import('./cloud.mjs');return getClient();});let editing=null,syncing=false,authenticated=false;const get=api.getState;
 function input(label,value,parent,opts={}){const id='entry-'+crypto.getRandomValues(new Uint32Array(1))[0];const wrap=add('label',label,parent);wrap.htmlFor=id;const e=add('input',undefined,wrap);e.id=id;e.type=opts.type||'number';e.value=value??'';e.dataset.field=opts.field;if(e.type==='number'){e.min=opts.min??'0';e.max=opts.max??'1440';e.step=opts.step??'0.01';e.inputMode='decimal';}if(opts.placeholder)e.placeholder=opts.placeholder;return e;}
 function removeButton(row){const b=add('button','Remover este trecho',row,'remove');b.type='button';b.onclick=()=>row.remove();}
 function treadmillRow(t={}){appendRhythm($('treadmill-list'),t,{incline:editing?.kind==='treadmill',removable:true});}
 function stairRow(t={}){const row=add('div',undefined,$('stairs-list'),'entry-row');const label=add('label','Direção',row),select=add('select',undefined,label);select.dataset.field='direction';for(const [v,txt] of [['up','Subida'],['down','Descida']]){const o=add('option',txt,select);o.value=v;}select.value=t.direction||'up';input('Degraus por lance (ex.: 5 + 5)',t.flights?.join(' + ')||'',row,{type:'text',field:'flights',placeholder:'5 + 5'});input('Duração só nas escadas (min) · opcional',t.minutes,row,{field:'minutes',min:.01});input('Minuto inicial na sessão · opcional',t.offset,row,{field:'offset',min:0});removeButton(row);}
 function openDetails(s){editing={id:s.id,base:editFingerprint(s),kind:s.kind};$('detail-description').textContent=s.kind==='treadmill'?'Esteira · km, tempo, pace opcional e inclinação por trecho.':'Ao ar livre · confirme os trechos realizados. A distância GPS, quando disponível, é preservada.';$('detail-pace').value=s.pace||'';$('corrected-minutes').value=s.correctedMinutes?Math.round(analyze(s).active/60000*100)/100:'';$('manual-km').value=s.manualKm??'';$('detail-notes').value=s.notes||'';$('treadmill-fields').hidden=false;$('manual-km-wrap').hidden=s.kind!=='treadmill';$('use-plan').hidden=!s.plannedRhythms?.length;$('stairs-fields').hidden=s.kind==='treadmill';$('stairs-list').replaceChildren();$('treadmill-list').replaceChildren();for(const t of (s.kind==='treadmill'?s.treadmill:s.efforts)||[])treadmillRow(t);for(const t of s.stairs||[])stairRow(t);$('detail-dialog').showModal();}
 $('session-detail').onclick=()=>{const s=get().current;if(s)openDetails(s);};$('detail-cancel').onclick=()=>$('detail-dialog').close();$('add-treadmill').onclick=()=>treadmillRow();$('add-stair').onclick=()=>stairRow();$('use-plan').onclick=()=>{if(!editing)return;const session=sessionForEdit(get().sessions,editing.id);$('treadmill-list').replaceChildren();for(const t of session.plannedRhythms||[])treadmillRow(t);$('corrected-minutes').value=(session.plannedRhythms||[]).reduce((n,t)=>n+t.minutes,0)+(session.stairs||[]).reduce((n,t)=>n+(Number(t.minutes)||0),0);};
 $('detail-form').onsubmit=async e=>{e.preventDefault();if(!editing)return;const s=sessionForEdit(get().sessions,editing.id);if(editFingerprint(s)!==editing.base){api.notify('A caminhada mudou durante a edição. Reabra os detalhes para conferir.',true);return;}const correction=$('corrected-minutes').value?Number($('corrected-minutes').value):null,minutes=correction??analyze({...s,correctedMinutes:null}).active/60000;
 const read=(row,field)=>row.querySelector('[data-field="'+field+'"]').value;
 let treadmill;try{treadmill=readRhythms($('treadmill-list'));}catch(error){api.notify(error.message,true);return;}
 const stairs=Array.from($('stairs-list').children).map(r=>({direction:read(r,'direction'),flights:read(r,'flights').trim().split(/[+,;\s]+/).filter(Boolean).map(Number),minutes:read(r,'minutes')?Number(read(r,'minutes')):null,offset:read(r,'offset')?Number(read(r,'offset')):null}));
 if(treadmill.some(t=>!(t.speed>0&&t.minutes>0&&t.incline>=0))||stairs.some(t=>!t.flights.length||t.flights.some(x=>!Number.isInteger(x)||x<1||x>10000))){api.notify('Informe velocidade, duração e degraus válidos.',true);return;}
 const total=treadmill.reduce((a,t)=>a+t.minutes,0)+(s.kind==='treadmill'?0:stairs.reduce((a,t)=>a+(t.minutes||0),0));if(total>minutes+.1){api.notify('Os trechos ultrapassam o tempo ativo. Confira as durações ou corrija o tempo.',true);return;}
 const timed=stairs.filter(t=>t.offset!==null&&t.minutes!==null).sort((a,b)=>a.offset-b.offset);if(timed.some((t,i)=>t.offset+t.minutes>minutes+.1||(i>0&&t.offset<timed[i-1].offset+timed[i-1].minutes))){api.notify('Confira os horários das escadas: há sobreposição ou tempo fora da caminhada.',true);return;}
 const previous={at:new Date().toISOString(),correctedMinutes:s.correctedMinutes??null,manualKm:s.manualKm??null,pace:s.pace||'',treadmill:s.treadmill||[],efforts:s.efforts||[],stairs:s.stairs||[],notes:s.notes||''};s.revisions=[...(s.revisions||[]),previous];s.correctionOriginalActive=analyze({...s,correctedMinutes:null}).originalActive;s.correctedMinutes=correction;s.pace=$('detail-pace').value;s.notes=$('detail-notes').value;s.treadmill=s.kind==='treadmill'?treadmill:[];s.efforts=s.kind!=='treadmill'?treadmill:[];s.stairs=s.kind==='treadmill'?[]:stairs;s.manualKm=s.kind==='treadmill'&&$('manual-km').value!==''?Number($('manual-km').value):null;s.profileSnapshot??=payloadOf(get().profile);s.analysis=analyze(s);try{await api.save();$('detail-dialog').close();if(get().current?.id===s.id)$('notes').value=s.notes;api.refresh();api.notify('Detalhes salvos. As estimativas foram recalculadas.');if(authenticated&&!get().current)sync();}catch{api.notify('Falha no salvamento. Exporte um backup antes de sair.',true);}};
 function filtered(){const from=$('filter-from').value,to=$('filter-to').value;if(from&&to&&from>to)return [];return get().sessions.filter(s=>{const d=new Date(s.start),key=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');return s.status==='finished'&&(!from||key>=from)&&(!to||key<=to);});}
 $('filter-from').onchange=$('filter-to').onchange=api.refresh;
 function report(){const sessions=filtered();if(!sessions.length){api.notify('Não há caminhadas no período escolhido.',true);return;}const root=$('print-report');root.replaceChildren();add('h1','Borali · relatório de caminhadas',root);add('p','Período: '+($('filter-from').value||'início do histórico')+' até '+($('filter-to').value||'hoje')+'\nGerado em '+new Date().toLocaleString('pt-BR')+'\nValores estimados não são medições clínicas.',root);
 for(const s of sessions){const r=analyze(s,get().profile),a=add('article',undefined,root,'report-session');add('h2',new Date(s.start).toLocaleString('pt-BR')+' · '+(s.kind==='treadmill'?'Esteira':'Ao ar livre'),a);add('p','Intervalada: '+(s.interval?'sim':'não informado/contínua')+'\nTempo ativo: '+n(r.active/60000)+' min; original: '+n(r.originalActive/60000)+' min; pausas: '+n(r.paused/60000)+' min\nDistância: '+n(r.km)+' km · '+r.kmSource+'\nPassos estimados: '+(r.stepsRange?r.stepsRange.map(n).join(' a ')+' (faixa por tempo e ritmo)':n(r.steps))+'\nCalorias ativas estimadas: '+n(r.kcal)+' kcal; totais estimadas: '+n(r.grossKcal)+' kcal\nDegraus informados: '+r.stairCount,a);add('p','Perfil usado: peso '+n(r.profileUsed.weight)+' kg; altura '+n(r.profileUsed.height)+' cm; idade '+n(r.profileUsed.age)+' anos.\n'+r.method+'\nPassos ≈ distância(m) ÷ comprimento do passo(m).\nComprimento usado: '+n(r.stepCm)+' cm. '+(r.stepMethod||'Não disponível.'),a);
 for(const t of s.plannedRhythms||[])add('p','Planejado (não é prova de realização): '+n(t.distance)+' km em '+n(t.minutes)+' min · pace '+formatPace(t.paceSeconds)+'/km',a);for(const t of (s.kind==='treadmill'?s.treadmill:s.efforts)||[])add('p','Trecho confirmado: '+n(t.distance??t.speed*t.minutes/60)+' km em '+n(t.minutes)+' min · pace '+formatPace(t.paceSeconds??3600/t.speed)+'/km',a);
 for(const t of r.parts)add('p',t.label+' · '+n(t.minutes)+' min · '+n(t.met)+' MET\n'+t.formula,a);for(const t of s.stairs||[])add('p','Escada: '+t.flights.join(' + ')+' = '+t.flights.reduce((a,b)=>a+b,0)+' degraus; duração '+n(t.minutes)+' min; minuto inicial '+n(t.offset),a);if(r.issues.length)add('p','Limitações: '+r.issues.join(' '),a);if(s.notes)add('p','Observação: '+s.notes,a);add('p','Revisões: '+(s.revisions?.length||0)+'; método '+r.version,a);}
 add('h2','Fontes e metodologia',root);for(const [title,url] of SOURCES){const p=add('p',undefined,root);add('span',title+' — ',p);const a=add('a',url,p);a.href=url;}add('p','Escadas substituem o tempo correspondente da caminhada. Não há bônus duplicado de passos ou calorias. Idade é usada para verificar a faixa de aplicação; peso e altura não comprovam gasto individual. Perfil anterior preservado por sessão.',root);root.hidden=false;window.print();}
 $('report').onclick=report;window.addEventListener('afterprint',()=>{$('print-report').hidden=true;});
 async function sync(){if(syncing)return;if(get().current){api.notify('Finalize a caminhada para sincronizar; ela continua salva neste aparelho.');return;}syncing=true;$('cloud-sync').disabled=true;$('sync-feedback').textContent='Conectando e conferindo revisões…';try{await api.save();const {syncState}=await import('./cloud.mjs');const before=structuredClone(get()),result=await syncState(before.sessions,before.profile);if(JSON.stringify(get().sessions)!==JSON.stringify(before.sessions)||JSON.stringify(get().profile)!==JSON.stringify(before.profile))throw new Error('Dados mudaram durante a sincronização. Tente novamente.');api.setState(result);await api.save();authenticated=true;$('cloud-status').textContent='Sincronizado com Supabase';$('sync-feedback').textContent='Sincronizado em '+new Date().toLocaleTimeString('pt-BR')+'. Só mostramos esta confirmação após a gravação no servidor.';api.refresh();}catch(e){$('cloud-status').textContent='Dados locais · sincronização pendente';$('sync-feedback').textContent=e.message||'Não foi possível conectar. Seus dados locais foram preservados.';}finally{syncing=false;$('cloud-sync').disabled=false;}}
 async function auth(create){const input=$('cloud-password'),email=$('cloud-email');if(!email.checkValidity()){email.reportValidity();return;}if(!input.checkValidity()){input.reportValidity();return;}$('cloud-login').disabled=$('cloud-create').disabled=true;try{const {login}=await import('./cloud.mjs');const session=await login(email.value.trim(),input.value,create);input.value='';if(!session){$('sync-feedback').textContent='Conta solicitada. Confirme o e-mail recebido e depois volte aqui para entrar. Se o serviço recusar o envio, confira a configuração de e-mail do projeto.';return;}authenticated=true;await sync();}catch(e){$('sync-feedback').textContent=e.code==='invalid_credentials'?'E-mail ou senha incorretos. Confira o e-mail ou use Esqueci minha senha.':'Não foi possível entrar: '+e.message;}finally{$('cloud-login').disabled=$('cloud-create').disabled=false;}}
 $('cloud-form').onsubmit=e=>{e.preventDefault();auth(false);};$('cloud-create').onclick=()=>auth(true);$('cloud-sync').onclick=sync;
 return {openDetails,filtered,sync,afterSave:()=>{if(authenticated&&!get().current)sync();},pending:()=>{$('cloud-status').textContent='Salvo no aparelho · alterações pendentes';}};
}
